import type { NextConfig } from "next";

import personRedirects from "./src/data/person-redirects.json";

/**
 * Escape a URL path for a Next.js redirect `source` (path-to-regexp syntax):
 * BORME names keep characters like "(" or "*" after encodeURIComponent.
 */
function literalPath(path: string): string {
  return path.replace(/[()*+?:{}\\]/g, (c) => `\\${c}`);
}

const nextConfig: NextConfig = {
  // Person pages whose BORME name changed when the parser was fixed (e.g. a
  // glued "DON" or a name cut by a page footer): keep old links and rankings.
  // Generated by scripts/borme_person_redirects.py on each full BORME rebuild.
  async redirects() {
    return Object.entries(personRedirects as Record<string, string>).map(([from, to]) => ({
      source: literalPath(`/persones/${encodeURIComponent(from)}`),
      destination: `/persones/${encodeURIComponent(to)}`,
      permanent: true,
    }));
  },
  async rewrites() {
    return {
      // Company pages are ISR-cached, so they can't read searchParams. The
      // `?name=` used for anonymised DNIs ("*** 0721 **") becomes a path segment.
      beforeFiles: [
        {
          source: "/empreses/:id",
          has: [{ type: "query", key: "name", value: "(?<name>.+)" }],
          destination: "/empreses/:id/nom/:name",
        },
      ],
    };
  },
};

export default nextConfig;
